package dev.steelcode.core.impl.registry;

import com.google.gson.JsonObject;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.ApiStatus;

import java.util.function.Supplier;

/**
 * A recipe waiting to be written by datagen.
 *
 * @param unlockedBy   item or tag (flexible reference) that unlocks it in the recipe book; {@code null} = none
 * @param automatic    generated by a family/material: dropped if it collides with an identical recipe
 * @param result       result item (flexible reference)
 * @param fallbackFrom if dropped because of a collision, replaced by a stonecutter recipe from this item ({@code null} = none)
 */
@ApiStatus.Internal
public record RecipeEntry(ResourceLocation id, Supplier<JsonObject> json, Object unlockedBy, String bookCategory,
                          boolean automatic, Object result, Object fallbackFrom, int fallbackCount) {
}
